const pageData = await browserjs(tabId, () => {
  const crumbs = Array.from(document.querySelectorAll('.crumbs li, .crumbs a, .crumbs span')).map(c => c.textContent.trim()).filter(Boolean);
  const filterButtons = Array.from(document.querySelectorAll('.filter-button, .chip-button')).map(b => b.textContent.trim().replace(/\s+/g, ' '));

  // Find all cards or items in the discover grid
  const items = Array.from(document.querySelectorAll('.card, .item, .discover-item, .card-grid li, [data-component*="item"], .item-title, .result-item, .music-grid-item, [class*="card"]')).map(el => {
